{
  "title": "Discussion about living and working abroad in Slovakia and Austria",
  "topics": [
    {
      "id": "living-abroad",
      "title": "Living abroad experiences",
      "claims": [
        {
          "text": "Some participants live in Slovakia or have moved abroad.",
          "evidence": [1, 43]
        },
        {
          "text": "User P2 mentions acquaintances in Austria and Poland.",
          "evidence": [3]
        },
        {
          "text": "User P3 has at least two acquaintances in Austria, one recently arrived and another living there for several years.",
          "evidence": [12, 13]
        },
        {
          "text": "User P3 has been living in Austria since November 2025.",
          "evidence": [49, 54]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Finding jobs abroad",
      "claims": [
        {
          "text": "Finding a job abroad is described as difficult but possible within two months.",
          "evidence": [16, 17]
        },
        {
          "text": "LinkedIn is recommended for job searching.",
          "evidence": [18]
        },
        {
          "text": "User P3 sent around 100 applications, resulting in only three interviews.",
          "evidence": [21, 22, 23]
        },
        {
          "text": "Most job postings require local language proficiency.",
          "evidence": [26, 27]
        },
        {
          "text": "There are cases where candidates with limited language skills are still hired.",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely influences hiring decisions.",
          "evidence": [32]
        },
        {
          "text": "Salary expectations in Europe are higher than in Ukraine, but many overlook it.",
          "evidence": [35]
        },
        {
          "text": "User P3 accepted a low salary after initially demanding a higher one.",
          "evidence": [37]
        },
        {
          "text": "Language level B2 is most often requested, sometimes B1, certifications usually not required.",
          "evidence": [46]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language requirements and barriers",
      "claims": [
        {
          "text": "German is the primary language spoken in Austria, but English is also used.",
          "evidence": [14, 15]
        },
        {
          "text": "User P3 communicates in English with the group.",
          "evidence": [15]
        },
        {
          "text": "The language barrier makes everyday interactions uncomfortable for some.",
          "evidence": [47, 51, 52]
        },
        {
          "text": "User P1 feels not confident speaking outside of work.",
          "evidence": [52]
        }
      ]
    },
    {
      "id": "salary-discussion",
      "title": "Salary discussion",
      "claims": [
        {
          "text": "User P3's position paid higher than minimum but still low compared to expectations.",
          "evidence": [37]
        },
        {
          "text": "User P3 believes salaries in Europe are generally higher than in Ukraine.",
          "evidence": [35]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Which Austrian company does P1 work for?",
      "evidence": [9]
